#include <algorithm>
#include <cstdint>
#include <iostream>
#include <vector>
struct E{int from,to;std::int64_t w;};
int main(){int n,m;std::int64_t price;std::cin>>n>>m>>price;std::vector<E>es;std::vector<std::vector<int>>g(n);while(m--){int u,v;std::int64_t c;std::cin>>u>>v>>c;es.push_back({u-1,v-1,price-c});g[u-1].push_back(v-1);}constexpr std::int64_t inf=std::int64_t{1}<<60;std::vector<std::int64_t>d(n,inf);d[0]=0;for(int pass=1;pass<n;++pass){auto next=d;for(auto e:es)if(d[e.from]!=inf)next[e.to]=std::min(next[e.to],d[e.from]+e.w);if(next==d)break;d.swap(next);}std::vector<bool>bad(n);std::vector<int>q;for(auto e:es)if(d[e.from]!=inf&&d[e.from]+e.w<d[e.to]&&!bad[e.to]){bad[e.to]=true;q.push_back(e.to);}for(std::size_t h=0;h<q.size();++h)for(int v:g[q[h]])if(!bad[v]){bad[v]=true;q.push_back(v);}std::cout<<(bad[n-1]?-1:std::max(std::int64_t{0},-d[n-1]))<<'\n';}

