for cc,compiler in [('gcc','g++'),('clang','clang++')]:
 for id,(lib,variants) in configs.items():
  old=(frozen/'Graph'/lib).read_text();sub=(frozen/'Verify/current/submissions'/f'{id}.cpp').read_text();assert sub.count(old)==1
  for v in variants:
   tu=p/f'{stage}_{cc}_{id}_{v}.cpp';tu.write_text(sub.replace(old,(p.parent/id/f'{v}.hpp').read_text()));exe=tu.with_suffix('');cmd=['taskset','-c','8',compiler,'-std=c++23','-O2',str(tu),'-o',str(exe)]
   if cc=='clang':cmd.insert(4,'--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15')
   subprocess.run(cmd,check=True,capture_output=True);text=exe.with_suffix('.text');subprocess.run(['objcopy','--dump-section','.text='+str(text),str(exe)],check=True,capture_output=True)
   build.append({'id':id,'compiler':cc,'variant':v,'command':cmd,'tu_sha256':hashlib.sha256(tu.read_bytes()).hexdigest(),'binary_sha256':hashlib.sha256(exe.read_bytes()).hexdigest(),'text_sha256':hashlib.sha256(text.read_bytes()).hexdigest()})
 print('built',cc,flush=True)
 with open('/tmp/sirkit_four_hours_20261022/benchmark_graph.lock','w') as lock:
  fcntl.flock(lock,fcntl.LOCK_EX)
  for id,(_,variants) in configs.items():
   for case in cases:
