    med={v:statistics.median(x) for v,x in vals.items()};ratio={v:med[v]/med['baseline'] for v in variants};records[f"{cc}/{id}/{case['case']}"]={'raw_ms':vals,'median_ms':med,'ratio':ratio,'input_sha256':case['input_sha256'],'expected_sha256':case['expected_sha256'],'kind':case['kind']};print(cc,id,case['case'],{v:round(x,3) for v,x in ratio.items()},flush=True)
