 run=['taskset','-c','8',str(exe)];x=subprocess.run(run,input=stdin,capture_output=True,env={**os.environ,'ASAN_OPTIONS':'detect_leaks=0'});assert x.returncode==0,(run,x.stdout,x.stderr)
