 records.append({'kind':kind,'command':cmd,'run_command':run,'stdout':x.stdout.decode(),'stderr':x.stderr.decode(),'returncode':x.returncode});print(kind,'PASS',flush=True)
for cc,compiler in [('gcc','g++'),('clang','clang++')]:
 for skip in [False,True]:
