   tu=p/f'pp_{id}_{tag}.cpp';tu.write_text('#include "'+str(root/'Graph'/lib)+'"\n');cmd=[compiler,*flags,'-E','-P',str(tu)];x=subprocess.run(cmd,capture_output=True,text=True,check=True);assert (api+': invalid start vertex' in x.stdout)==(not skip);assert (api+': cost must be in [-1e9, 1e9]' in x.stdout)==(not skip);assert api+': too many vertices' in x.stdout;records.append({'kind':f'preprocess/{id}/{tag}','command':cmd,'input_validation_removed':skip,'capacity_protection_retained':True})
  for reverse in [False,True]:
   libs=[v[0] for v in configs.values()];libs=libs[::-1] if reverse else libs;tu=p/f'aggregate_{tag}_{reverse}.cpp';tu.write_text(''.join('#include "'+str(root/'Graph'/lib)+'"\n' for lib in libs)+'int main(){WGraph g(1);std::vector<std::int64_t>d;return BellmanFord(g,d,0)||SPFA(g,d,0);}\n');exe=tu.with_suffix('');run_compile(['taskset','-c','8',compiler,*flags,str(tu),'-o',str(exe)],exe,f'aggregate/{tag}/{reverse}')
for id,(lib,api,kind) in configs.items():
 for skip in [False,True]:
  flags=['-std=c++23','-O1','-g','-Wall','-Wextra','-Werror','-pedantic-errors','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15','-fsanitize=address,undefined','-fno-omit-frame-pointer']
  if skip:flags+=['-DSKIP_RUNTIME_CHECKS']
  exe=p/f'asan_{id}_{skip}';run_compile(['taskset','-c','8','clang++',*flags,'-DSIRKIT_TEST_NEGATIVE_PATH_SOURCE="'+str(root/'Graph'/lib)+'"','-DSIRKIT_TEST_NEGATIVE_PATH_API='+api,'-DSIRKIT_TEST_NEGATIVE_PATH_KIND='+str(kind),str(root/'Verify/current/tests/negative_shortest_paths_reference_test.cpp'),'-o',str(exe)],exe,f'asan/{id}/{skip}')
